export interface DomainEvent {
  type: string;
  occurredAt: string;
  payload: any;
}

export class OrderAggregate {
  id: string = '';
  status: string = 'CREATED';
  totalCents: number = 0;
  version: number = 0;

  // Rehydrate state from event history
  static fromHistory(events: DomainEvent[]): OrderAggregate {
    const aggregate = new OrderAggregate();
    for (const event of events) {
      aggregate.apply(event);
      aggregate.version++;
    }
    return aggregate;
  }

  private apply(event: DomainEvent): void {
    switch (event.type) {
      case 'OrderCreated':
        this.id = event.payload.orderId;
        this.totalCents = event.payload.totalCents;
        this.status = 'PENDING';
        break;
      case 'OrderPaid':
        this.status = 'PAID';
        break;
      case 'OrderCancelled':
        this.status = 'CANCELLED';
        break;
    }
  }
}
